package cn.academy.port.wireless;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerLevel;import cn.academy.port.solar.ImagFluxGenerator;import cn.academy.port.machine.ImagFluxReceiver;
public class ClassicWirelessSavedData {private static final Map<ServerLevel,ClassicWirelessSavedData> DATA=new IdentityHashMap<>();private final ClassicWirelessGraph graph;public static ClassicWirelessSavedData get(ServerLevel level){return DATA.computeIfAbsent(level,ClassicWirelessSavedData::new);}public static ClassicWirelessGraph.Pos pos(BlockPos p){return new ClassicWirelessGraph.Pos(p.getX(),p.getY(),p.getZ());}private static BlockPos block(ClassicWirelessGraph.Pos p){return new BlockPos(p.x(),p.y(),p.z());}public ClassicWirelessGraph graph(){return graph;}private ClassicWirelessSavedData(ServerLevel l){graph=new ClassicWirelessGraph(new ClassicWirelessGraph.Resolver(){public boolean isLoaded(ClassicWirelessGraph.Pos p){return l.hasChunkAt(block(p));}public ImagFluxNode node(ClassicWirelessGraph.Pos p){var tile=l.tiles.get(block(p));return tile instanceof ClassicWirelessNodeBlockEntity n&&n.available()?n:null;}public ImagFluxMatrix matrix(ClassicWirelessGraph.Pos p){var tile=l.tiles.get(block(p));return tile instanceof ClassicWirelessMatrixBlockEntity m&&m.available()?m:null;}public ImagFluxGenerator generator(ClassicWirelessGraph.Pos p){return l.generators.get(block(p));}public ImagFluxReceiver receiver(ClassicWirelessGraph.Pos p){return l.receivers.get(block(p));}public List<ClassicWirelessGraph.Pos> wirelessBlocksWithin(ClassicWirelessGraph.Pos p,double r,int max){return l.tiles.keySet().stream().map(ClassicWirelessSavedData::pos).filter(v->v.distanceSquared(p)<=r*r).limit(max).toList();}},new Random(123),()->{});}}
